@app.function
def grade_payload(submission, questions, answers, digests):
    """Pure scoring core shared by the CLI and generated offline notebook."""
    if not isinstance(submission, dict) or set(submission) != {"dataset_version", "responses"}:
        raise ValueError("Submission requires exactly dataset_version and responses")
    if submission["dataset_version"] != questions["dataset_version"]:
        raise ValueError("Submission dataset_version does not match")
    if not isinstance(submission["responses"], list):
        raise ValueError("responses must be a JSON array")
    predictions = {}
    for row in submission["responses"]:
        if not isinstance(row, dict) or set(row) != {"id", "label"}:
            raise ValueError("Each response requires exactly id and label")
        qid, label = row["id"], row["label"]
        if not isinstance(qid, str) or qid not in answers:
            raise ValueError(f"Unknown question ID: {qid!r}")
        if qid in predictions:
            raise ValueError(f"Duplicate question ID: {qid}")
        if not isinstance(label, str) or label not in LABELS:
            raise ValueError(f"Invalid label for {qid}; choose one of {LABELS}")
        predictions[qid] = label
    correct = sum(predictions.get(qid) == answer["label"] for qid, answer in answers.items())
    per_class = {}
    for label in LABELS:
        members = [qid for qid, answer in answers.items() if answer["label"] == label]
        hits = sum(predictions.get(qid) == label for qid in members)
        per_class[label] = {"correct": hits, "total": len(members),
                            "recall": hits / len(members), "exact": f"{hits}/{len(members)}"}
    macro = sum(Fraction(row["correct"], row["total"]) for row in per_class.values()) / len(LABELS)
    return {
        "dataset_version": questions["dataset_version"], **digests,
        "synthetic_only": True, "total": len(answers), "answered": len(predictions),
        "missing": len(answers) - len(predictions), "correct": correct,
        "score": correct / len(answers), "exact_score": f"{correct}/{len(answers)}",
        "macro_average_recall": float(macro), "macro_average_exact": str(macro),
        "per_class": per_class,
        "false_supported_claim_count": sum(
            label == "supported" and answers[qid]["label"] != "supported"
            for qid, label in predictions.items()),
        "missing_ids": [qid for qid in answers if qid not in predictions],
        "incorrect_ids": [qid for qid, label in predictions.items() if answers[qid]["label"] != label],
        "interpretation": "Closed synthetic exercise, not model, profit, coverage or production certification.",
    }


@app.function
def evidence_html(evidence):
    """Readable evidence tables with no inferred or omitted field values."""
    def display(value):
        if value is None:
            return "Not supplied (null)"
        if isinstance(value, bool):
            return "Yes" if value else "No"
        return str(value)

    def rows(value, prefix=""):
        if isinstance(value, dict):
            return [row for key, child in value.items()
                    for row in rows(child, f"{prefix} / {key}" if prefix else key)]
        if isinstance(value, list):
            if not value:
                return [(prefix, "Empty list")]
            return [row for index, child in enumerate(value, 1)
                    for row in rows(child, f"{prefix} / {index}")]
        return [(prefix.replace("_", " "), display(value))]

    contract = html.escape(evidence.get("contract", ""))
    fields = {key: value for key, value in evidence.items() if key != "contract"}
    if "record_a" in fields:
        left = fields.pop("record_a")
        candidates = fields.pop("candidates_b")
        records = [left, *candidates]
        keys = list(dict.fromkeys(key for record in records for key in record))
        header = "<tr><th scope='col'>Field</th><th scope='col'>Record A</th>"
        header += "".join(f"<th scope='col'>Record B{index}</th>" for index in range(1, len(candidates) + 1)) + "</tr>"
        body = "".join("<tr><th scope='row'>" + html.escape(key.replace("_", " ")) + "</th>"
                       + "".join("<td>" + html.escape(display(record.get(key))) + "</td>" for record in records)
                       + "</tr>" for key in keys)
        comparison = "<div class='orc-scroll'><table><thead>" + header + "</thead><tbody>" + body + "</tbody></table></div>"
    else:
        comparison = ""
    body = "".join("<tr><th scope='row'>" + html.escape(key) + "</th><td>"
                   + html.escape(value) + "</td></tr>" for key, value in rows(fields))
    return ("<p class='orc-contract'><strong>Rules for this case:</strong> " + contract + "</p>"
            + comparison + "<div class='orc-scroll'><table><tbody>" + body + "</tbody></table></div>")


@app.function
def submission_from_choices(choices):
    return {"dataset_version": QUESTIONS["dataset_version"],
            "responses": [{"id": qid, "label": label} for qid, label in choices.items() if label is not None]}


